INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-qc-iv-rank-gate', 'qc-iv-rank-gate', 'IV-Rank Gate for Credit Spreads', 'Reusable gate: sell defined-risk put credit verticals only when the IV rank of the symbol''s CBOE vol index (252 days) is at least 50. Measured as a before/after effect on existing strategies. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-iv-rank-gate. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; host Sharpe -0.20, max DD -19.3%; gate cut drawdowns on sma30 (-54.5% to -17.2%) and Donchian (-78.5% to -36.5%).', 'python', 'backtested', 'docs/specs/strategies/qc-iv-rank-gate.md', '["research-only","failed","quantconnect-idea","options","defined-risk","gate"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-turn-of-the-month', 'qc-turn-of-the-month', 'Turn of the Month (option verticals)', 'Call debit vertical on SPY, QQQ, DIA, IWM held from trading day -2 to +3 around month end. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-turn-of-the-month. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe -0.41, CAGR -3.0%, max DD -65.6%, 1028 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-turn-of-the-month.md', '["research-only","failed","quantconnect-idea","options","defined-risk","calendar"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-opex-week', 'qc-opex-week', 'Option-Expiration Week Effect', 'Call debit vertical held during the monthly option-expiration week on the equity ETF twins. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-opex-week. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe -0.44, CAGR -2.8%, max DD -63.6%, 996 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-opex-week.md', '["research-only","failed","quantconnect-idea","options","defined-risk","calendar"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-regime-put-vrp', 'qc-regime-put-vrp', 'Regime-Gated Put VRP', '25-delta put credit verticals (~45 DTE, 50% profit take, close at 21 DTE) only in calm, uptrend regimes: VIX <= 25, VIX/VIX3M <= 1, SPY above its 200-day SMA. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-regime-put-vrp. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe 0.09, CAGR 0.1%, max DD -3.7%, 167 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-regime-put-vrp.md', '["research-only","failed","quantconnect-idea","options","defined-risk","vrp"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-futures-trend-carry', 'qc-futures-trend-carry', 'Futures Trend + Carry on Core 7', 'Signal from the Core 7 futures 12-month trend strength and a carry proxy; expressed as debit verticals on the ETF twins. No naked futures. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-futures-trend-carry. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe -0.32, CAGR -3.3%, max DD -60.1%, 829 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-futures-trend-carry.md', '["research-only","failed","quantconnect-idea","options","defined-risk","trend"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-vix-term-gate', 'qc-vix-term-gate', 'VIX Term-Structure Gate', 'Reusable gate: bullish entries only in contango (VIX/VIX3M < 1); includes the VIX-predicts-index-returns quintile table. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-vix-term-gate. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; host Sharpe -0.05, max DD -4.7%; contango gate leaves Sharpe unchanged on sma30 and Donchian.', 'python', 'backtested', 'docs/specs/strategies/qc-vix-term-gate.md', '["research-only","failed","quantconnect-idea","options","defined-risk","gate"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-asset-class-trend', 'qc-asset-class-trend', 'Asset-Class Trend (10-month SMA)', 'Monthly: call debit vertical (~60 DTE) on each Core 7 ETF twin above its 10-month SMA; flat otherwise. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-asset-class-trend. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe -0.10, CAGR -1.6%, max DD -59.1%, 1116 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-asset-class-trend.md', '["research-only","failed","quantconnect-idea","options","defined-risk","trend"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-momentum-rotation', 'qc-momentum-rotation', 'Asset-Class Momentum Rotation', 'Monthly: call debit verticals on the top 2 Core 7 ETF twins by 12-1 month momentum, only when momentum is positive. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-momentum-rotation. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe 0.06, CAGR 0.2%, max DD -29.7%, 594 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-momentum-rotation.md', '["research-only","failed","quantconnect-idea","options","defined-risk","momentum"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-gold-fed-model', 'qc-gold-fed-model', 'Gold Market Timing (Fed model)', 'Monthly: GLD call debit vertical when the S&P earnings yield (Shiller, lagged 3 months) is above 2x the 10-year yield. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-gold-fed-model. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe -0.26, CAGR -0.7%, max DD -21.2%, 95 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-gold-fed-model.md', '["research-only","failed","quantconnect-idea","options","defined-risk","macro"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-oil-predicts-equity', 'qc-oil-predicts-equity', 'Crude Oil Predicts Equity Returns', 'Monthly rolling regression of next-month SPY excess return on last-month USO return; call debit verticals on SPY/QQQ when the forecast beats T-bills. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-oil-predicts-equity. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe 0.42, CAGR 3.0%, max DD -15.4%, 341 trades, deflated Sharpe 0.39; no better than the same spread without the signal (0.44).', 'python', 'backtested', 'docs/specs/strategies/qc-oil-predicts-equity.md', '["research-only","failed","quantconnect-idea","options","defined-risk","macro"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-same-month-seasonality', 'qc-same-month-seasonality', 'Same-Calendar-Month Seasonality', 'Monthly: call debit verticals on the top 2 Core 7 twins by average same-calendar-month return over prior years, when positive. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-same-month-seasonality. Pre-set rule (Sharpe>0.5, deflated Sharpe>0.9, max DD<25%, beats baseline): FAIL; Sharpe -0.24, CAGR -1.7%, max DD -48.6%, 511 trades.', 'python', 'backtested', 'docs/specs/strategies/qc-same-month-seasonality.md', '["research-only","failed","quantconnect-idea","options","defined-risk","seasonality"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb)
